import { describe, it, expect, beforeEach } from 'vitest';
import { WatchlistStore } from '../app/watchlist-store';
import type { TmdbMovie } from '../app/movie';

const movie = (id: number, title: string): TmdbMovie => ({
  id,
  title,
  release_date: '2024-01-01',
  poster_path: '/poster.jpg',
  overview: 'A test movie.',
});

describe('WatchlistStore items use `seen`', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('adds items with seen=false and no legacy `watched` property', () => {
    const store = new WatchlistStore();
    store.add(movie(1, 'Dune'));
    const [item] = store.items();
    expect(item.seen).toBe(false);
    expect('watched' in item).toBe(false);
  });

  it('toggleWatched flips `seen` and watchedCount counts seen items', () => {
    const store = new WatchlistStore();
    store.add(movie(1, 'Dune'));
    store.add(movie(2, 'Alien'));
    store.toggleWatched(1);
    const items = store.items();
    expect(items.find((i) => i.id === 1)?.seen).toBe(true);
    expect(items.find((i) => i.id === 2)?.seen).toBe(false);
    expect(store.watchedCount()).toBe(1);
  });

  it('migrates legacy persisted `watched` items to `seen` on load', () => {
    // Discover the storage key by watching what a fresh store writes.
    const probe = new WatchlistStore();
    probe.add(movie(99, 'probe-title'));
    const key = Object.keys(localStorage).find((k) =>
      (localStorage.getItem(k) ?? '').includes('probe-title')
    );
    expect(key).toBeTruthy();
    if (!key) return;

    const legacyItems = [
      { id: 1, title: 'Legacy', watched: true },
      { id: 2, title: 'Legacy Too', watched: false },
    ];
    // Match whatever envelope shape the store already persists.
    const current = localStorage.getItem(key);
    let legacy: unknown = legacyItems;
    if (current) {
      const parsed = JSON.parse(current);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        const clone: Record<string, unknown> = { ...(parsed as Record<string, unknown>) };
        const arrKey = Object.keys(clone).find((k) => Array.isArray(clone[k]));
        if (arrKey) {
          clone[arrKey] = legacyItems;
          legacy = clone;
        }
      }
    }
    localStorage.setItem(key, JSON.stringify(legacy));

    const store = new WatchlistStore();
    const items = store.items();
    expect(items).toHaveLength(2);
    expect(items.find((i) => i.id === 1)?.seen).toBe(true);
    expect(items.find((i) => i.id === 2)?.seen).toBe(false);
    expect(items.every((i) => !('watched' in i))).toBe(true);

    // Any subsequent save must persist the renamed field only.
    store.toggleWatched(2);
    expect(localStorage.getItem(key) ?? '').not.toContain('"watched"');
  });
});

