import { describe, expect, it } from 'vitest';
import type {
    Movie,
    TmdbMovieDetail,
    WatchItem,
} from './movie';

// Compile-time assertions: `seen` is a required boolean key and the old
// `watched` key is gone from WatchItem. Each alias resolves to `unknown`
// while its invariant holds and to `never` once it breaks, so the helpers
