    it('still uses watched for its own status field', () => {
        const movie: Movie = {
            id: 3,
            title: 'Spirited Away',
            releaseDate: '2001-07-20',
            rating: 5,
            watched: true,
        };
        expect(movie.watched).toBe(true);
    });
});

